mapper.select:
SELECT c.id_consulta AS idConsulta, c.fecha_hora AS fechaHora, c.peso AS peso, c.estatura AS estatura, c.talla AS talla, c.imc AS imc, c.observaciones AS observaciones, c.id_paciente AS idPaciente, c.id_medico AS idMedico, c.id_dieta AS idDieta,
-- Datos del Paciente p.codigo_acceso AS "paciente.codigoAcceso", pu.nombre AS "paciente.usuario.nombre", pu.apellido_paterno AS "paciente.usuario.apellidoPaterno", pu.apellido_materno AS "paciente.usuario.apellidoMaterno",
-- Datos del Médico m.numero_personal AS "medico.numeroPersonal", mu.nombre AS "medico.usuario.nombre", mu.apellido_paterno AS "medico.usuario.apellidoPaterno",
-- Datos de la Dieta d.id_dieta AS "dieta.idDieta", d.nombre AS "dieta.nombre"
FROM consulta c INNER JOIN paciente p ON c.id_paciente = p.id_paciente INNER JOIN usuario pu ON p.id_usuario = pu.id_usuario INNER JOIN medico m ON c.id_medico = m.id_medico INNER JOIN usuario mu ON m.id_usuario = mu.id_usuario LEFT JOIN dieta d ON c.id_dieta = d.id_dieta
AND c.id_consulta = #{idConsulta}
AND c.id_paciente = #{idPaciente}
AND c.id_medico = #{idMedico}
AND DATE(c.fecha_hora) = #{fecha}
ORDER BY c.fecha_hora DESC;

